"""
Demo 1 -- The Dichotomy Explorer: solvability vs. triviality.

Enumerates several finite group actions and confirms, for each, that the
symmetric distinguishing task (an invariant injective function) is solvable
if and only if the action is trivial (Theorem B).
"""
from __future__ import annotations
from itertools import permutations
from typing import Callable, Hashable, List, Sequence, Tuple

Perm = Tuple[int, ...]

def compose(p: Perm, q: Perm) -> Perm:
    return tuple(p[q[i]] for i in range(len(q)))

def identity(n: int) -> Perm:
    return tuple(range(n))

def symmetric_group(n: int) -> List[Perm]:
    return list(permutations(range(n)))

def cyclic_group(n: int) -> List[Perm]:
    return [tuple((i + k) % n for i in range(n)) for k in range(n)]

def orbits(group: Sequence[Perm], points: Sequence[Hashable],
           act: Callable[[Perm, Hashable], Hashable]):
    seen: set = set(); out = []
    for x in points:
        if x in seen: continue
        orb = frozenset(act(g, x) for g in group)
        seen |= orb; out.append(orb)
    return out

def is_trivial(group, points, act) -> bool:
    return all(act(g, x) == x for g in group for x in points)

def solvable(group, points, act) -> bool:
    return len(orbits(group, points, act)) == len(list(points))

def natural(g: Perm, x: Hashable) -> Hashable:
    return g[x]

def regular(g: Perm, x: Hashable) -> Hashable:
    return compose(g, x)

def main() -> None:
    n = 3
    cases = [
        ("S_3 natural on labels", symmetric_group(n), list(range(n)), natural),
        ("C_3 natural on labels", cyclic_group(n), list(range(n)), natural),
        ("trivial group on labels", [identity(n)], list(range(n)), natural),
        ("S_3 regular on itself", symmetric_group(n), symmetric_group(n), regular),
    ]
    for name, g, pts, act in cases:
        t, s = is_trivial(g, pts, act), solvable(g, pts, act)
        print(f"{name:28s}  trivial={t!s:5}  solvable={s!s:5}  match={t==s}")

if __name__ == "__main__":
    main()

"""
Demo 2 -- Freeness via orbit-map injectivity (Theorem A).

For each point x the orbit map g |-> g.x is built explicitly, and its
injectivity is compared against the fixed-point definition of freeness.
"""
from __future__ import annotations
from itertools import permutations
from typing import Hashable, List, Sequence, Tuple

Perm = Tuple[int, ...]

def compose(p: Perm, q: Perm) -> Perm:
    return tuple(p[q[i]] for i in range(len(q)))

def identity(n: int) -> Perm:
    return tuple(range(n))

def symmetric_group(n: int) -> List[Perm]:
    return list(permutations(range(n)))

def is_free(group, points, act, ident) -> bool:
    return all(not (act(g, x) == x and g != ident)
               for x in points for g in group)

def orbit_maps_injective(group, points, act) -> bool:
    for x in points:
        imgs = [act(g, x) for x_ in [x] for g in group]
        if len(set(imgs)) != len(imgs):
            return False
    return True

def natural(g: Perm, x: Hashable) -> Hashable:
    return g[x]

def regular(g: Perm, x: Hashable) -> Hashable:
    return compose(g, x)

def main() -> None:
    for n in (2, 3, 4):
        g = symmetric_group(n)
        nat_free = is_free(g, list(range(n)), natural, identity(n))
        nat_inj = orbit_maps_injective(g, list(range(n)), natural)
        reg_free = is_free(g, g, regular, identity(n))
        reg_inj = orbit_maps_injective(g, g, regular)
        print(f"S_{n}: natural free={nat_free} inj={nat_inj} | "
              f"regular free={reg_free} inj={reg_inj}")

if __name__ == "__main__":
    main()

