function IS_FREE(group, points, act, identity):
  for each x in points:
    for each g in group:
      if g != identity and act(g, x) == x:
        return False
  return True

function ORBIT_PARTITION(group, points, act):
  seen <- empty set; result <- empty list
  for each x in points:
    if x in seen: continue
    orbit <- { act(g, x) : g in group }
    seen <- seen union orbit
    append orbit to result
  return result

function TASK_SOLVABLE(group, points, act):
  seen <- empty set; n_orbits <- 0
  for each x in points:
    if x in seen: continue
    orbit <- { act(g, x) : g in group }
    seen <- seen union orbit
    n_orbits <- n_orbits + 1
  n_points <- |points|
  return (n_orbits == n_points, n_orbits, n_points)
